CONTENT_SECURITY_POLICY = ("default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")

OPERATOR_HTML = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Browser Agent Operator</title><link rel="stylesheet" href="/operator.css"></head><body><main><header><div class="brand"><span class="brand-mark" aria-hidden="true">BA</span><h1>Browser Agent</h1></div><div class="header-meta"><span id="status" class="status-badge">idle</span><span id="activity">0 steps</span><button id="cancel" class="danger compact" type="button" disabled>Cancel</button><button id="toggle-diagnostics" class="secondary compact" type="button" aria-controls="diagnostics-panel" aria-expanded="true">Hide diagnostics</button></div></header><div id="columns" class="columns"><section class="conversation-column" aria-labelledby="conversation-title"><h2 id="conversation-title" class="visually-hidden">Conversation</h2><div class="conversation-scroll"><div id="conversation" aria-live="polite"></div><div id="downloads-wrap" class="interaction-card downloads-card" hidden><h3>Downloads</h3><ul id="downloads"></ul></div><div id="result-wrap" hidden><pre id="result"></pre></div></div><div id="composer" class="composer"><div id="start-composer"><label for="task" class="visually-hidden">Task</label><textarea id="task" required rows="2" placeholder="Describe the browser task…"></textarea><div class="composer-row"><label class="url-field" for="start-url"><span>Start URL</span><input id="start-url" type="url" required autocomplete="url" placeholder="https://example.com"></label><button id="start" type="button">Start run</button></div></div><div id="interaction" class="interaction-card" hidden><p id="question" hidden></p><div id="user-panel" hidden><label for="user-response">Response</label><textarea id="user-response" rows="2"></textarea><button id="send-response" type="button">Send response</button></div><div id="confirmation-panel" hidden><p class="card-label">Confirmation required</p><button id="approve" type="button">Approve</button><button id="reject" class="secondary" type="button">Reject</button></div><form id="secret-panel" hidden autocomplete="on"><p class="card-label">Secure information required</p><div id="secret-fields"></div><button id="send-secret" type="submit">Submit securely</button></form></div><p id="error" role="alert"></p></div></section><aside id="diagnostics-panel" class="diagnostics" aria-labelledby="diagnostics-title"><div class="diagnostics-heading"><h2 id="diagnostics-title">Diagnostics</h2><button id="diagnostics-follow" class="secondary compact" type="button" hidden>Jump to latest</button></div><div class="run-head"><span>Run</span><span id="run-id">None</span></div><ol id="diagnostics" aria-live="polite"></ol><ol id="timeline" hidden></ol><p id="timeline-empty" hidden></p></aside></div></main><script src="/operator.js" defer></script></body></html>"""

