PROVIDER_TRACE_HTML = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Provider Trace</title><link rel="stylesheet" href="/operator.css"></head><body><main><header><div class="brand"><span class="brand-mark" aria-hidden="true">BA</span><h1>Provider Trace</h1></div><a href="/">Back to Chat</a></header><section class="conversation-scroll"><p id="trace-state">Loading provider trace…</p><div id="provider-traces" aria-live="polite"></div></section></main><script src="/provider-trace.js" defer></script></body></html>"""

PROVIDER_TRACE_JAVASCRIPT = r"""'use strict';
(() => {
  const output=document.getElementById('provider-traces'),state=document.getElementById('trace-state');
  const runId=new URLSearchParams(globalThis.location.search).get('run_id');
  let lastSequence=-1,pending=false;
  const text=(parent,tag,value)=>{const node=document.createElement(tag);node.textContent=value;parent.append(node);};
  const render=payload=>{const traces=Array.isArray(payload.traces)?payload.traces:[],sequence=traces.length?traces[traces.length-1].sequence:0;if(sequence===lastSequence)return;lastSequence=sequence;output.replaceChildren();state.textContent=payload.enabled?(traces.length?'':'No provider attempts recorded yet.'):'Provider trace is disabled for this run.';traces.forEach(trace=>{const card=document.createElement('article');card.className='interaction-card';text(card,'h2',`Attempt ${trace.sequence}`);['timestamp','decision_sequence','attempt_number','model','tool_choice','offered_tool_names','previous_step_count','user_interaction_count','application_event_count','http_status','duration_ms','finish_reason','tool_call_count','assistant_content_present','selected_tool_name','result_status','safe_error_type'].forEach(key=>text(card,'p',`${key}: ${Array.isArray(trace[key])?trace[key].join(', '):trace[key]??'—'}`));output.append(card);});};
  const poll=async()=>{if(pending)return;pending=true;try{const response=await fetch(`/runs/${encodeURIComponent(runId)}/provider-traces`,{credentials:'same-origin'}),payload=await response.json();if(!response.ok)throw new Error(payload&&payload.error&&payload.error.message||'Request failed.');render(payload);}catch(error){state.textContent=error&&error.message?'Unable to load provider trace.':'Unable to load provider trace.';}finally{pending=false;}};
  if(!runId){state.textContent='Open this screen from a run, or add a run_id query parameter.';return;}poll();setInterval(poll,1000);
})();"""

OPERATOR_CSS = """:root{color-scheme:dark;--ink:#edf1f5;--muted:#98a3b1;--paper:#0b0e13;--card:#151a22;--raised:#1c232d;--accent:#72dfbd;--accent-strong:#2bb78c;--line:#2a3340;--danger:#f0727b;--focus:#a0efd7;--header:58px;--drawer:390px}*{box-sizing:border-box}html,body{height:100%}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{height:100%;display:flex;flex-direction:column}header{height:var(--header);flex:none;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 22px;border-bottom:1px solid var(--line);background:rgba(11,14,19,.96)}h1,h2,h3,p{margin-top:0}.brand,.header-meta,.composer-row,.diagnostics-heading,.run-head{display:flex;align-items:center}.brand{gap:10px}.brand-mark{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#173c32;color:var(--accent);font-size:.72rem;font-weight:800}h1{font-size:1rem;margin:0}.header-meta{gap:10px;color:var(--muted);font-size:.85rem}.status-badge{color:var(--accent);background:#16352d;border:1px solid #285748;border-radius:999px;padding:3px 9px}.columns{min-height:0;flex:1;display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,var(--drawer));transition:grid-template-columns .2s ease}.columns.diagnostics-closed{grid-template-columns:minmax(0,1fr)}.conversation-column{min-width:0;min-height:0;display:flex;flex-direction:column}.conversation-scroll{min-height:0;flex:1;overflow-y:auto;overscroll-behavior:contain;padding:34px max(24px,calc((100% - 760px)/2)) 24px}#conversation{min-height:100%}.message,.interaction-card{width:min(100%,760px);padding:13px 16px;border:1px solid var(--line);border-radius:14px;margin:16px auto;white-space:pre-wrap;overflow-wrap:anywhere}.message.user{width:fit-content;max-width:min(78%,680px);background:#183c33;border-color:#2a5c4d;margin-right:0}.message.agent{background:transparent;border-color:transparent;padding-left:2px}.interaction-card{background:var(--card);box-shadow:0 12px 35px rgba(0,0,0,.2)}.downloads-card{white-space:normal}.composer{position:sticky;bottom:0;z-index:3;flex:none;padding:12px max(24px,calc((100% - 760px)/2)) 18px;background:linear-gradient(0deg,var(--paper) 76%,transparent)}#start-composer,#interaction{width:min(100%,760px);margin:0 auto;background:var(--card);border:1px solid #374252;border-radius:16px;padding:10px;box-shadow:0 14px 36px rgba(0,0,0,.35)}#interaction{padding:14px}.composer-row{gap:10px;margin-top:8px}.url-field{min-width:0;flex:1;display:flex;align-items:center;gap:9px;margin:0;color:var(--muted);font-size:.78rem}.url-field span{flex:none}.url-field input{padding:7px 9px}.composer-row button{flex:none;margin:0}label{display:block;font-weight:650;margin:8px 0 5px}.card-label{color:var(--muted);font-size:.82rem;font-weight:750;text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px}input,textarea{width:100%;font:inherit;color:var(--ink);background:#0d1117;padding:10px 12px;border:1px solid #364151;border-radius:9px;resize:vertical}#task{border:0;background:transparent;min-height:54px;max-height:150px;resize:none}input:hover,textarea:hover{border-color:#536174}input:focus-visible,textarea:focus-visible,button:focus-visible,a:focus-visible{outline:2px solid var(--focus);outline-offset:2px}button{font:inherit;font-weight:700;border:1px solid transparent;border-radius:9px;padding:9px 14px;margin:10px 7px 0 0;background:var(--accent-strong);color:#07130f;cursor:pointer}button:hover:not(:disabled){background:var(--accent)}button.secondary{background:#27313d;color:var(--ink);border-color:#3a4655}button.danger{background:#a83f49;color:#fff}button.compact{margin:0;padding:6px 10px;font-size:.82rem}button:disabled{opacity:.42;cursor:not-allowed}#error{width:min(100%,760px);min-height:1.3em;margin:5px auto 0;color:var(--danger);font-size:.85rem}.diagnostics{min-width:340px;min-height:0;border-left:1px solid var(--line);background:#10141a;padding:18px;font:12px/1.45 ui-monospace,monospace;display:flex;flex-direction:column;overflow:hidden}.diagnostics-heading,.run-head{justify-content:space-between;gap:10px}.diagnostics-heading h2{font:700 1rem system-ui,sans-serif;margin-bottom:12px}.run-head{padding:8px 10px;background:#0b0f14;border:1px solid var(--line);border-radius:9px}.run-head span:last-child{min-width:0;overflow-wrap:anywhere;text-align:right}#diagnostics{flex:1;min-height:180px;margin:14px 0 0;padding-left:2.4rem;overflow:auto;overscroll-behavior:contain;scrollbar-color:#465467 #11161d}.diagnostics li{min-width:max-content;max-width:680px;padding-left:5px;margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere}#downloads{padding-left:1.3rem}a{color:var(--accent)}pre{white-space:pre-wrap}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}[hidden]{display:none!important}@media(max-width:900px){:root{--drawer:340px}.conversation-scroll,.composer{padding-left:18px;padding-right:18px}.header-meta #activity{display:none}}@media(max-width:700px){header{height:auto;min-height:58px;padding:10px 12px;align-items:flex-start}.header-meta{justify-content:flex-end;flex-wrap:wrap}.columns{display:block}.diagnostics{position:fixed;inset:0;z-index:20;width:100%;min-width:0;border:0;padding:18px}.conversation-column{height:calc(100vh - 68px)}.conversation-scroll{padding:20px 12px}.composer{padding:10px 10px 12px}.message.user{max-width:90%}.composer-row{align-items:stretch;flex-direction:column}.url-field{align-items:flex-start;flex-direction:column;gap:3px}.composer-row button{width:100%}.diagnostics li{min-width:0}.brand-mark{display:none}}"""
